import test from 'node:test';import assert from 'node:assert/strict';
import {compileAtlas,route,connectivity,makeVehicle,stepVehicle,fixedStepper,streamCells,STEP} from './continuous-world-core.mjs';
const atlas=compileAtlas({nodes:[{id:'lowbank',x:0,z:0},{id:'bridge',x:100,z:0},{id:'town',x:200,z:0},{id:'airfield',x:200,z:200}],edges:[{id:'road1',from:'lowbank',to:'bridge',modes:['walk','drive']},{id:'road2',from:'bridge',to:'town',modes:['walk','drive']},{id:'air',from:'town',to:'airfield',modes:['fly']}]});
test('road routes are reciprocal and flight uses distinct access',()=>{assert.deepEqual(route(atlas,'lowbank','town','drive').path,['lowbank','bridge','town']);assert.deepEqual(route(atlas,'town','lowbank','walk').path,['town','bridge','lowbank']);assert.equal(route(atlas,'lowbank','airfield','drive'),null);assert.deepEqual(connectivity(atlas,'lowbank','walk').unreachable,['airfield']);});
test('duplicate coordinates and invalid endpoints are rejected',()=>{assert.throws(()=>compileAtlas({nodes:[{id:'x',x:0,z:0},{id:'x',x:1,z:1}]}));assert.throws(()=>compileAtlas({nodes:[{id:'x',x:0,z:0}],edges:[{id:'e',from:'x',to:'missing'}]}));});
test('fixed timestep produces stable results across render cadence',()=>{let a=makeVehicle(),b=makeVehicle();const aa=fixedStepper(dt=>a=stepVehicle(a,{throttle:1,steer:.3},dt));const bb=fixedStepper(dt=>b=stepVehicle(b,{throttle:1,steer:.3},dt));for(let i=0;i<120;i++)aa(STEP);for(let i=0;i<60;i++)bb(STEP*2);assert.ok(Math.abs(a.x-b.x)<1e-8);assert.ok(Math.abs(a.z-b.z)<1e-8);});
test('flight moves and stays above ground',()=>{let v=makeVehicle({type:'flight',y:10});for(let i=0;i<180;i++)v=stepVehicle(v,{throttle:1,pitch:.7,roll:.2},STEP);assert.ok(v.z>0);assert.ok(v.y>=1);});
test('streaming is bounded',()=>assert.equal(streamCells({x:0,z:0,radius:2}).length,25));
